// ScopedResourcePolicyModuleIDs returns module IDs for resource policies at different scope levels.
// If genTree is true, it generates IDs for each prefix of the scope (from most specific to least specific).
// If genTree is false, it returns only the exact-scope ID.
func ScopedResourcePolicyModuleIDs(resource, version, scope string, genTree bool) []ModuleID {
	if !genTree || scope == "" {
		return []ModuleID{ResourcePolicyModuleID(resource, version, scope)}
	}

	// Generate the tree from most specific to least specific
	moduleIDs := []ModuleID{ResourcePolicyModuleID(resource, version, scope)}

	for i := len(scope) - 1; i >= 0; i-- {
		if scope[i] == '.' {
			moduleIDs = append(moduleIDs, ResourcePolicyModuleID(resource, version, scope[:i]))
		}
	}

	// Add the empty scope as the root
	moduleIDs = append(moduleIDs, ResourcePolicyModuleID(resource, version, ""))

	return moduleIDs
}

// ScopedPrincipalPolicyModuleIDs returns module IDs for principal policies at different scope levels.
// If genTree is true, it generates IDs for each prefix of the scope (from most specific to least specific).
// If genTree is false, it returns only the exact-scope ID.
