		if scope[i] == '.' {
			moduleIDs = append(moduleIDs, PrincipalPolicyModuleID(principal, version, scope[:i]))
		}
	}

	// Add the empty scope as the root
	moduleIDs = append(moduleIDs, PrincipalPolicyModuleID(principal, version, ""))

	return moduleIDs
}
