// GetFirstMatch returns the compilation unit for the first matching module ID from the candidates list.
func (idx *index) GetFirstMatch(candidates []namer.ModuleID) (*policy.CompilationUnit, error) {
	idx.mu.RLock()
	defer idx.mu.RUnlock()

	for _, id := range candidates {
		if _, ok := idx.modIDToFile[id]; !ok {
			continue
		}

		p, err := idx.loadPolicy(id)
		if err != nil {
			return nil, err
		}

		cu := &policy.CompilationUnit{
			ModID:       id,
			Definitions: map[namer.ModuleID]*policyv1.Policy{id: p},
		}

		// add dependencies
		if err := idx.addDepsToCompilationUnit(cu, id); err != nil {
			return nil, fmt.Errorf("failed to load dependencies of %s: %w", namer.PolicyKey(p), err)
		}

		// load ancestors of the policy
		for _, ancestor := range cu.Ancestors() {
			p, err := idx.loadPolicy(ancestor)
			if err != nil {
				return nil, fmt.Errorf("failed to load ancestor %q of scoped policy %s: %w", ancestor.String(), namer.PolicyKey(p), err)
			}
			cu.AddDefinition(ancestor, p)
			if err := idx.addDepsToCompilationUnit(cu, ancestor); err != nil {
				return nil, fmt.Errorf("failed to load dependencies of ancestor %q of %s: %w", ancestor.String(), namer.PolicyKey(p), err)
			}
		}

		return cu, nil
	}

	// No match found
	return nil, nil
}
